def __init__(self, name=None, *, image=None):
    if name is None:
        name = self._infer_app_name()
    self._name = name
    self._image = image
    self._blueprint = {}
    self._client_mount = None
    self._function_mounts = {}
    if image is not None:
        # TODO(erikbern): reconsider this later
        self._blueprint["_image"] = self._image

    super().__init__()

